INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "邓茂七", "aliases": ["鄧茂七"], "era": "明", "birth_year": null, "death_year": null, "description": "邓茂七在福建起事。", "biography": null, "status": "draft", "id": "d3bbc093-e80f-5b2f-9e7e-32d98f66cec5"}, {"name": "王骥", "aliases": ["王驥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德9年（年号对照1434年）三月，王骥出任兵部尚书。", "biography": null, "status": "draft", "id": "4a558c65-f1f5-51f5-90df-5aa57564c8bb"}, {"name": "思机发", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "思机发为明军征讨对象。", "biography": null, "status": "draft", "id": "4b70c1c9-54ce-526f-96a9-c56865625ed0"}, {"name": "叶宗留", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代浙江起事者。正统13年（年号对照1448年），本表记录了叶宗留的活动。", "biography": null, "status": "draft", "id": "ec439357-6f91-5e57-bf4e-8e31b3fccefe"}, {"name": "石璞（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统13年（年号对照1448年）五月，石璞出任工部尚书。", "biography": null, "status": "draft", "id": "cf73a116-9338-5fa8-81a2-a33c0b3a9657"}, {"name": "陈懋", "aliases": ["宁阳侯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈懋以宁阳侯身份巡边阅兵。", "biography": null, "status": "draft", "id": "e5696099-627f-57a5-b989-87e71d1b2e68"}, {"name": "张益（明代内阁大学士）", "aliases": ["張益"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統14年（1449年）五月，张益以翰林侍读学士身份入阁。", "biography": null, "status": "draft", "id": "bf30e4a6-0680-524c-8fda-baf36857f248"}, {"name": "宋瑛（明代西宁侯）", "aliases": ["西寧侯宋瑛"], "era": "明", "birth_year": null, "death_year": null, "description": "宋瑛（明代西宁侯）奉命总督大同兵马。", "biography": null, "status": "draft", "id": "92e8d889-8425-5265-9804-923964c42e5e"}, {"name": "陈怀", "aliases": ["平乡伯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈怀率军在松潘作战。", "biography": null, "status": "draft", "id": "1f04c0a5-7d79-541c-ab2f-9938d38aad23"}, {"name": "井源", "aliases": ["駙馬都尉井源"], "era": "明", "birth_year": null, "death_year": null, "description": "井源分领京军操练。", "biography": null, "status": "draft", "id": "3b37176e-36ab-5594-9ccc-208d54034f72"}, {"name": "也先", "aliases": ["瓦剌太师也先"], "era": "明", "birth_year": null, "death_year": null, "description": "也先所部为明廷防备对象。", "biography": null, "status": "draft", "id": "d9af0d41-e6b4-5de2-9de3-32e0f8826f3c"}, {"name": "王直（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统8年（年号对照1443年）正月，王直出任吏部尚书。", "biography": null, "status": "draft", "id": "1982b813-f0ef-5cfa-937e-1e3ac5b21d41"}, {"name": "朱祁钰", "aliases": ["明景帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明景帝，正統14年（1449年）九月，朱祁钰即皇帝位。", "biography": null, "status": "draft", "id": "beac1b51-89b3-5024-bf3a-2d45bc5afe2b"}, {"name": "朱冕", "aliases": ["武進伯朱冕"], "era": "明", "birth_year": null, "death_year": null, "description": "朱冕在阳和交战并阵亡。", "biography": null, "status": "draft", "id": "c42f0b3f-8664-5e34-9625-8bbec8bc6e71"}, {"name": "朱勇（明代成国公）", "aliases": ["成国公朱勇"], "era": "明", "birth_year": null, "death_year": null, "description": "朱勇以成国公身份出征。", "biography": null, "status": "draft", "id": "a9e23ee9-c846-5b85-a72f-af00920c9f10"}, {"name": "张辅", "aliases": ["张文弼"], "era": "明", "birth_year": null, "death_year": null, "description": "张辅率军在爱子江交战。", "biography": null, "status": "draft", "id": "ef0d049d-1c37-5697-84d4-4274dfac2d2d"}, {"name": "丁铉", "aliases": ["丁鉉"], "era": "明", "birth_year": null, "death_year": null, "description": "丁铉以刑部侍郎身份安抚灾民。", "biography": null, "status": "draft", "id": "6d99efb9-7230-5bf4-a06b-1e25b4e86a14"}, {"name": "王永和", "aliases": ["工部侍郎王永和"], "era": "明", "birth_year": null, "death_year": null, "description": "王永和以工部侍郎身份治理水患。", "biography": null, "status": "draft", "id": "a7e0f678-7f76-5015-b9b4-2d11799ff15f"}, {"name": "王佐（明代户部尚书）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统6年（年号对照1441年）十二月，王佐出任户部尚书。", "biography": null, "status": "draft", "id": "785d16fe-76d6-5a21-b805-c17f85f2acd9"}, {"name": "邝埜", "aliases": ["鄺埜"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统10年（年号对照1445年）九月，邝埜出任兵部尚书。", "biography": null, "status": "draft", "id": "302b8316-0ba4-54c4-873d-92e8bd98f046"}, {"name": "曹鼐", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統5年（1440年）二月，曹鼐以翰林侍讲身份入阁。", "biography": null, "status": "draft", "id": "6049135d-64fe-5c8a-b811-901a0a9575f8"}, {"name": "徐有贞", "aliases": ["徐有貞"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）正月，徐有贞以兵部尚书兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "a2c2c258-40a6-5fa1-b82d-a741f40d91fb"}, {"name": "于谦", "aliases": ["于謙"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统14年（年号对照1449年）八月，于谦出任兵部尚书。", "biography": null, "status": "draft", "id": "3f189404-652f-5b32-9509-a7b9157c87b2"}, {"name": "孙氏（明宣宗孝恭章皇后）", "aliases": ["孝恭章皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "孙氏（明宣宗孝恭章皇后）由贵妃被立为皇后。", "biography": null, "status": "draft", "id": "15138702-a78a-5b56-ab98-4cb1f1b546f3"}, {"name": "朱见深", "aliases": ["明宪宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宪宗，天順8年（1464年）正月，朱见深即皇帝位。", "biography": null, "status": "draft", "id": "71fde383-1de5-538d-bb25-2cc9e4cc7d1c"}]'::jsonb)
