SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明英宗在南郊祭祀天地", "description": "正统十四年正月甲午，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年正月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f3ab625-f905-5a33-b6a9-c818ac18bca9"}, {"title": "明廷减免浙江和福建的银课", "description": "正统十四年正月乙巳，朝廷免除浙江、福建应缴纳的银课。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年正月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "59425b55-7a0f-5df9-a57d-86835c6a8803"}, {"title": "邓茂七在延平被明军击杀", "description": "正统十四年二月丁巳，御史丁瑄和指挥刘福率兵，在延平击杀邓茂七。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年二月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "debecb48-0cfa-5907-97e9-615eedb4a561"}, {"title": "王骥在金沙江和鬼哭山击败思机发后撤军", "description": "正统十四年二月己巳，本纪记王骥在金沙江击败思机发，又在鬼哭山获胜，随后撤回军队。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年二月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7a6bfbfd-a65a-5e19-8825-5e6925ba3165"}, {"title": "徐恭奉命征讨处州叶宗留，石璞参赞军务", "description": "正统十四年二月辛未，朝廷任命指挥佥事徐恭为总兵官，率兵征讨处州叶宗留，工部尚书石璞参赞军务。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年二月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5a14755f-7ae1-564f-bd32-c372878d1a8e"}, {"title": "明英宗前往天寿山", "description": "正统十四年三月戊子，明英宗朱祁镇前往天寿山。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年三月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cba90704-517f-5fea-a8c2-b729228993f8"}, {"title": "明英宗返回宫中", "description": "正统十四年三月癸巳，明英宗朱祁镇从天寿山返回宫中。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年三月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "11d9aadb-dad4-528d-8b0f-a31ed7d584b5"}, {"title": "处州起事者进攻崇安，吴刚遇害", "description": "正统十四年四月庚戌，来自处州的起事者进攻崇安，杀死都指挥吴刚。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年四月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dee207c7-5c0a-5b6d-bfd5-23896fbce3db"}, {"title": "湖广、贵州苗民中有人起事，朝廷派王骥征讨", "description": "正统十四年四月壬戌，本纪记湖广、贵州有苗民大规模起事，明廷派王骥领兵征讨。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年四月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b613e6e4-d2a8-5254-ae34-573b81b2ad30"}, {"title": "明廷派御史和宦官督办福建、浙江银课", "description": "正统十四年四月乙丑，朝廷派十三名御史与宦官共同督办福建、浙江的银课。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年四月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aad797c2-24f0-5603-9b8d-b61a3415c274"}, {"title": "陈懋击败沙县起事者", "description": "正统十四年五月丙戌，宁阳侯陈懋率兵击败沙县的起事者。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年五月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "91b01399-a5ea-5a7f-98a7-9282d961f5de"}, {"title": "发生旱灾，金英与司法官员复核囚案", "description": "正统十四年五月壬辰，本纪记发生旱灾，太监金英与司法衙门共同审查在押人员的案件。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年五月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8f28e15f-21d5-5fb7-a396-7d91bcf0fbeb"}, {"title": "张益以翰林侍读学士身份入阁", "description": "正統14年（1449年）五月，张益以翰林侍读学士身份入阁。", "start_year": 1449, "end_year": 1449, "time_original": "正統14年（1449年）五月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "227ee4fc-78c5-55fa-b175-9ca42b0b6252"}, {"title": "明廷处死汪澄和柴文显", "description": "正统十四年五月庚子，巡按福建御史汪澄被公开处决，前任巡按御史柴文显也被处死。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年五月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "18a9175e-10f3-55a8-a3c5-feb21ba6b14a"}, {"title": "本纪记靖州苗民进攻辰溪，高亮战死", "description": "正统十四年六月庚戌，本纪记靖州苗民中有人进攻辰溪，都指挥高亮在交战中死亡。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年六月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6d08f9a1-d547-575d-8aad-68622f38e629"}, {"title": "南京谨身殿等宫殿发生火灾", "description": "正统十四年六月丙辰，南京谨身殿等多处宫殿发生火灾。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年六月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7d07924-d580-5799-a28b-0677e7166720"}, {"title": "南京宫殿火灾后，明廷举行修省", "description": "正统十四年六月，南京宫殿发生火灾。同月甲子，明廷按本纪记载举行修省，以回应灾异。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年六月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ace316c0-18b2-5200-8a49-628e662b1037"}, {"title": "明廷调河南、山西轮休班军赴大同和宣府", "description": "正统十四年六月甲子条记，朝廷下诏把河南、山西正在轮休的班军全部调往大同和宣府。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年六月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ba1687ba-7adf-5c7b-8d04-15377a09e827"}, {"title": "宋瑛受命总督大同兵马", "description": "正统十四年六月乙丑，明廷任命西宁侯宋瑛总督大同兵马。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年六月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "928ff8a1-f27c-5706-862c-da432bf236a4"}, {"title": "明廷大赦天下", "description": "正统十四年六月己巳，朝廷下令大赦天下。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年六月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5dffd14-2e75-5bf0-988d-18a3ec2caf82"}, {"title": "陈怀、井源等分练京军以防备瓦剌", "description": "正统十四年六月戊寅，陈怀、井源、王贵、吴克勤和林寿分赴大同、宣府操练京军，防备瓦剌。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年六月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0f24e1b7-387d-5269-b156-5728d72d6202"}, {"title": "瓦剌也先进攻大同，参将吴浩战死", "description": "正统十四年七月己丑条记，瓦剌太师也先率军进攻大同，明军参将吴浩在作战中阵亡。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d174d9c3-ad89-51b9-8e93-f7048383c4a9"}, {"title": "明英宗下诏亲征，王直等劝阻", "description": "正统十四年七月己丑，明英宗朱祁镇在边军战败后下诏亲征。吏部尚书王直率群臣劝阻，英宗仍决定出征。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf210db7-5e20-56e3-81f8-7d061ed7a5c4"}, {"title": "明英宗命郕王朱祁钰留守京师", "description": "正统十四年七月癸巳，明英宗即将出征，命郕王朱祁钰留守京师。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "abb93620-38f1-5858-b615-61c4faf8e367"}, {"title": "明军在阳和战败，宋瑛和朱冕阵亡", "description": "正统十四年七月癸巳，西宁侯宋瑛、武进伯朱冕在阳和与瓦剌军交战。明军战败，宋瑛和朱冕阵亡。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "df628da2-2bcb-5ffe-9525-1c01a7767e7e"}, {"title": "明英宗亲征部队从京师出发", "description": "正统十四年七月甲午，明英宗朱祁镇率亲征军队从京师出发。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a70561f4-6386-53a2-a288-6b83483e1e4f"}, {"title": "明英宗亲征部队在龙虎台驻扎", "description": "正统十四年七月乙未，明英宗的亲征部队在龙虎台驻扎，本纪记军中当夜发生惊扰。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec48e81a-ee4f-50ca-93f6-3f17ce135c2a"}, {"title": "明英宗亲征部队抵达居庸关", "description": "正统十四年七月丁酉，明英宗的亲征部队抵达居庸关。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0622bad5-5a1b-5347-8a82-4ce5d3ba66de"}, {"title": "明英宗亲征部队抵达宣府，群臣请求停驻", "description": "正统十四年七月辛丑，明英宗的亲征部队抵达宣府。群臣屡次请求他停驻，英宗没有同意。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "72fb4086-3e0b-5251-8d5d-7f3cc0677203"}, {"title": "明英宗亲征部队抵达阳和", "description": "正统十四年七月丙午，明英宗的亲征部队抵达阳和。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年七月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e224002b-1c07-56e0-9ad2-76feb3a49198"}, {"title": "明英宗抵达大同，明军商议撤回", "description": "正统十四年八月戊申，明英宗的军队抵达大同。镇守太监郭敬进言，随后军中商议撤回。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8072014d-f49e-58f4-9c88-2edfccf9105f"}, {"title": "广宁伯刘安出任总兵官，镇守大同", "description": "正统十四年八月己酉，广宁伯刘安受命担任总兵官，镇守大同。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "245ed8ca-37ed-5a47-aa08-aa4c436fd941"}, {"title": "明英宗的亲征部队开始撤回", "description": "正统十四年八月庚戌，明英宗所率部队从大同一带开始撤回。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "14a41c72-0541-513d-9ca9-0ae063df9e11"}, {"title": "明英宗撤军途中抵达宣府", "description": "正统十四年八月丁巳，明英宗的部队在撤回途中抵达宣府。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d913c551-459c-5d70-b20f-c3f23b7687de"}, {"title": "瓦剌军逼近，明将吴克忠和吴克勤战死", "description": "正统十四年八月庚申，瓦剌大军逼近，明军恭顺侯吴克忠、都督吴克勤在交战中阵亡。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "36120511-6730-5f38-abfc-e4e3fd4dfc81"}, {"title": "朱勇和薛绶率援军在鹞儿岭战败", "description": "正统十四年八月庚申，成国公朱勇和永顺伯薛绶率部救援，在鹞儿岭遭瓦剌军伏击，所率部队覆没。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0655ea60-aa42-512e-a7ac-fd1c70772ae9"}, {"title": "明英宗所率明军在土木被围", "description": "正统十四年八月辛酉，明英宗所率明军抵达土木，被瓦剌军包围。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "12c245f5-3adb-520e-89d9-d908296ddd85"}, {"title": "土木之变，明军溃败，明英宗被俘", "description": "正统十四年八月壬戌，遭围困的明军在土木溃败，明英宗朱祁镇被俘。英国公张辅、驸马都尉井源、平乡伯陈怀等官员在此役遇难。本纪称死者数十万，《瓦剌传》记为死伤数十万。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6aaa36e5-3c1b-5dfc-8f9d-e0938b222af8"}, {"title": "王佐在土木之变中遇难", "description": "正统14年（年号对照1449年）八月，王佐在土木之变中遇难。", "start_year": 1449, "end_year": 1449, "time_original": "正统14年（年号对照1449年）八月；公元年核为1449年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "accd9461-ae3d-5201-b120-f9bbdae6df21"}, {"title": "邝埜在土木之变中遇难", "description": "正统14年（年号对照1449年）八月，邝埜在土木之变中遇难。", "start_year": 1449, "end_year": 1449, "time_original": "正统14年（年号对照1449年）八月；公元年核为1449年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "f9ae461b-2ea5-59b3-ba5a-9f0fa8d44292"}, {"title": "曹鼐死于土木之变", "description": "正統14年（1449年）八月，曹鼐死于土木之变。", "start_year": 1449, "end_year": 1449, "time_original": "正統14年（1449年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9beb945e-bc45-5fb7-a783-83f348396b7b"}, {"title": "张益死于土木之变", "description": "正統14年（1449年）八月，张益死于土木之变。", "start_year": 1449, "end_year": 1449, "time_original": "正統14年（1449年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "03c1c625-088f-58e6-9ebc-29dbfdb16505"}, {"title": "京师获悉土木战败，徐珵请南迁，于谦反对", "description": "正统十四年八月甲子，明军战败消息传到京师，群臣在朝廷聚集痛哭。侍讲徐珵（后改名徐有贞）建议南迁，兵部侍郎于谦反对。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a0ec526f-a8f3-5594-8bc5-853da9435cd1"}, {"title": "朱祁钰开始监国", "description": "正统14年（年号对照1449年）八月，朱祁钰开始监国。", "start_year": 1449, "end_year": 1449, "time_original": "正统14年（年号对照1449年）八月；公元年核为1449年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "871ba9f1-3385-51f2-9fe6-6ca88ca8b474"}, {"title": "明英宗被俘后抵达大同", "description": "正统十四年八月戊辰，明英宗朱祁镇被俘后抵达大同。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0316f96f-17a6-54e3-91bd-d3af2babf926"}, {"title": "皇太后命立朱见深为皇太子", "description": "正统十四年八月己巳，皇太后孙氏命立明英宗之子朱见深为皇太子。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f925d2ce-3044-591c-bfc8-92130e2031e9"}, {"title": "明英宗被俘期间抵达威宁海子", "description": "正统十四年八月辛未，明英宗朱祁镇被俘期间抵达威宁海子。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "209dd462-f6b1-5d8a-b946-3fad28879e30"}, {"title": "明英宗被俘期间抵达黑河", "description": "正统十四年八月甲戌，明英宗朱祁镇被俘期间抵达黑河。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "851ce418-9d55-5c82-8602-9af1e8bad413"}, {"title": "朱祁钰即皇帝位", "description": "正統14年（1449年）九月，朱祁钰即皇帝位。", "start_year": 1449, "end_year": 1449, "time_original": "正統14年（1449年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "0e9436c8-a4f3-542e-be05-34f0ec94d382"}, {"title": "明景帝遥尊明英宗为太上皇帝", "description": "正统十四年九月癸未，朱祁钰即位，当日遥尊仍在瓦剌军中的明英宗朱祁镇为太上皇帝。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d0ea6b59-d5ae-57e1-a320-e48ca748eb55"}, {"title": "明廷从河南调粮救济陕西饥民", "description": "正统十年十二月壬戌，朝廷调运河南粮食救济陕西饥民。卷末校记据《英宗实录》改旧作壬辰为壬戌。", "start_year": 1446, "end_year": 1446, "time_original": "正统十年十二月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5c7935ae-5323-58d3-9110-514167a2f2c5"}]'::jsonb)
